package com.shopsphere.marketplace.service;
import com.shopsphere.identity.domain.UserAccount;
import com.shopsphere.identity.repository.UserAccountRepository;
import com.shopsphere.marketplace.api.*;
import com.shopsphere.marketplace.domain.*;
import com.shopsphere.marketplace.repository.*;
import java.util.List;
import java.util.Locale;
import java.util.UUID;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
@Service
public class SellerCatalogueService {
 private final SellerRepository sellers; private final CategoryRepository categories; private final BrandRepository brands; private final ProductRepository products; private final ProductVariantRepository variants; private final ListingRepository listings; private final InventoryRepository inventory; private final InventoryMovementRepository movements; private final UserAccountRepository users;
 public SellerCatalogueService(SellerRepository sellers,CategoryRepository categories,BrandRepository brands,ProductRepository products,ProductVariantRepository variants,ListingRepository listings,InventoryRepository inventory,InventoryMovementRepository movements,UserAccountRepository users){this.sellers=sellers;this.categories=categories;this.brands=brands;this.products=products;this.variants=variants;this.listings=listings;this.inventory=inventory;this.movements=movements;this.users=users;}
 @Transactional public SellerProductResponse submitProduct(UUID userId,ProductSubmissionRequest request){Seller seller=approvedSeller(userId);Category category=categories.findById(request.categoryId()).filter(c->"ACTIVE".equals(c.getStatus())).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose an active category"));Brand brand=request.brandId()==null?null:brands.findById(request.brandId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Brand not found"));String slug=slugify(request.title())+"-"+UUID.randomUUID().toString().substring(0,8);Product product=products.save(new Product(category,brand,seller.getUser(),request.title().trim(),slug,request.description().trim()));return toSellerProduct(product);}
 @Transactional(readOnly=true) public List<SellerProductResponse> myProducts(UUID userId){approvedSeller(userId);return products.findAllByCreatedBy_IdOrderByCreatedAtDesc(userId).stream().map(this::toSellerProduct).toList();}
 @Transactional public ListingResponse createListing(UUID userId,CreateListingRequest request){Seller seller=approvedSeller(userId);Product product=products.findByIdAndProductStatus(request.productId(),"ACTIVE").orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only approved active products can be listed"));ProductVariant variant=request.variantId()==null?null:variants.findByIdAndProduct_Id(request.variantId(),product.getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Variant does not belong to this product"));String sku=request.sellerSku().trim();if(listings.existsBySeller_IdAndSellerSkuIgnoreCase(seller.getId(),sku))throw new ResponseStatusException(HttpStatus.CONFLICT,"Seller SKU already exists");if(request.shippingDaysMax()<request.shippingDaysMin())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Maximum shipping days must be greater than or equal to minimum shipping days");String currency=request.currency()==null?"INR":request.currency();String condition=request.condition()==null?"NEW":request.condition();Listing listing=listings.save(new Listing(product,variant,seller,sku,request.priceMinor(),currency,condition,(short)request.shippingDaysMin(),(short)request.shippingDaysMax(),(short)request.returnWindowDays(),request.warrantyText()));Inventory stock=inventory.save(new Inventory(listing,request.availableQuantity()));if(request.availableQuantity()>0)movements.save(new InventoryMovement(stock,"STOCK_RECEIVED",request.availableQuantity(),"Initial seller stock",seller.getUser()));return toListing(listing);}
 @Transactional(readOnly=true) public List<ListingResponse> myListings(UUID userId){Seller seller=approvedSeller(userId);return listings.findAllBySeller_IdOrderByCreatedAtDesc(seller.getId()).stream().map(this::toListing).toList();}
 @Transactional public ListingResponse pauseListing(UUID userId,UUID listingId){Seller seller=approvedSeller(userId);Listing listing=listings.findByIdAndSeller_Id(listingId,seller.getId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Listing not found"));if(!"ACTIVE".equals(listing.getListingStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only active listings can be paused");listing.pause();return toListing(listing);}
 @Transactional(readOnly=true) public List<SellerProductResponse> pendingProducts(){return products.findAllByProductStatusOrderByCreatedAtDesc("PENDING_REVIEW").stream().map(this::toSellerProduct).toList();}
 @Transactional public AdminProductResponse approveProduct(UUID productId){Product product=products.findById(productId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));if(!"PENDING_REVIEW".equals(product.getProductStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending products can be approved");product.approve();return toAdminProduct(product);}
 @Transactional public AdminProductResponse rejectProduct(UUID productId,String reason){Product product=products.findById(productId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));if(!"PENDING_REVIEW".equals(product.getProductStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending products can be rejected");product.reject(reason.trim());return toAdminProduct(product);}
 @Transactional(readOnly=true) public List<AdminListingResponse> pendingListings(){return listings.findAllByListingStatusOrderByCreatedAtDesc("PENDING_REVIEW").stream().map(this::toAdminListing).toList();}
 @Transactional public AdminListingResponse approveListing(UUID listingId){Listing listing=listings.findById(listingId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Listing not found"));if(!"PENDING_REVIEW".equals(listing.getListingStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending listings can be approved");if(!"ACTIVE".equals(listing.getProduct().getProductStatus())||!"APPROVED".equals(listing.getSeller().getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Product and seller must be approved before a listing can be published");listing.approve();return toAdminListing(listing);}
 @Transactional public AdminListingResponse rejectListing(UUID listingId,String reason){Listing listing=listings.findById(listingId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Listing not found"));if(!"PENDING_REVIEW".equals(listing.getListingStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Only pending listings can be rejected");listing.reject(reason.trim());return toAdminListing(listing);}
 private Seller approvedSeller(UUID userId){Seller seller=sellers.findByUserId(userId).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Complete seller onboarding first"));if(!"APPROVED".equals(seller.getStatus()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Seller account is awaiting approval or is not active");return seller;}
 private SellerProductResponse toSellerProduct(Product p){return new SellerProductResponse(p.getId(),p.getTitle(),p.getSlug(),p.getCategory().getName(),p.getProductStatus(),p.getRejectionReason());}
 private AdminProductResponse toAdminProduct(Product p){return new AdminProductResponse(p.getId(),p.getTitle(),p.getSlug(),p.getCategory().getName(),p.getBrand()==null?null:p.getBrand().getName(),p.getProductStatus(),p.getRejectionReason());}
 private ListingResponse toListing(Listing l){return new ListingResponse(l.getId(),l.getProduct().getId(),l.getProduct().getTitle(),l.getSellerSku(),l.getPriceMinor(),l.getCurrency(),l.getListingStatus(),inventory.findByListing_Id(l.getId()).map(Inventory::getAvailableQty).orElse(0));}
 private AdminListingResponse toAdminListing(Listing l){return new AdminListingResponse(l.getId(),l.getProduct().getId(),l.getProduct().getTitle(),l.getSeller().getId(),l.getSeller().getStoreName(),l.getSellerSku(),l.getPriceMinor(),l.getCurrency(),l.getListingStatus(),inventory.findByListing_Id(l.getId()).map(Inventory::getAvailableQty).orElse(0),l.getRejectionReason());}
 private String slugify(String title){String slug=title.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");return slug.isBlank()?"product":slug;}
}
